// Filas de las hojas calculadas del Sheet (cobertura, key-people, histórico, alertas).
// Sin dependencias: lo usan exportar-sheets.js y los nodos de código de n8n (exportar-n8n.js).

const COLS = {
  cobertura: ['funcion_id', 'area', 'nombre', 'criticidad', 'semaforo', 'icono', 'prioridad', 'cobertura', 'objetivo', 'skill_mas_debil', 'cubren', 'backup_en_desarrollo', 'candidatos_con_interes', 'impacto_ia', 'respuesta'],
  keyPeople: ['empleado_id', 'nombre', 'area', 'rol', 'oculta', 'funciones', 'skills'],
  historico: ['fecha', 'funcion_id', 'semaforo', 'cobertura', 'prioridad', 'evento'],
  bandeja: ['fecha', 'asunto', 'html'], // copia de cada email que envía el sistema: el panel la enseña sin depender de un buzón (D-22)
  alertas: ['alerta_id', 'fecha', 'evento', 'funcion_id', 'prioridad', 'cambio', 'tipo_accion', 'accion', 'empleado_id', 'skill_id', 'formacion_id', 'por_que', 'riesgo_si_no', 'decision', 'decidido_por', 'fecha_decision', 'grupo'],
};
const ICONO = { verde: '🟢', ambar: '🟡', rojo: '🔴' };

function filasCobertura(r, nombre) {
  return r.funciones.map(f => {
    const s = f.skills.reduce((a, b) => (b.cobertura < a.cobertura ? b : a));
    const debiles = f.skills.filter(x => x.semaforo !== 'verde');
    return [f.id, f.area, f.nombre, f.criticidad, f.semaforo, ICONO[f.semaforo], f.prioridad, f.cobertura, f.objetivo, s.skill,
      s.personas.map(nombre).join('; '),
      debiles.flatMap(x => x.backups_en_desarrollo).map(nombre).join('; '),
      debiles.flatMap(x => (x.candidatos || []).filter(c => c.con_interes).map(c => c.nombre)).join('; '),
      f.impacto_ia, f.respuesta === 'redisenar' ? 'rediseñar con IA' : 'cubrir'];
  });
}

function filasKeyPeople(r) {
  return r.key_people.map(k => [k.id, k.nombre, k.area, k.rol, k.oculta ? 'si' : 'no',
    k.funciones.map(f => f.funcion).join('; '), k.funciones.map(f => f.skill).join('; ')]);
}

function filasHistorico(r, fecha, evento) {
  return r.funciones.map(f => [fecha, f.id, f.semaforo, f.cobertura, f.prioridad, evento]);
}


// Automatizaciones con calendario (D-21): seguimiento de planes de backup y centinela de riesgo. No son agentes: aplican reglas.
// Implementa definiciones/reglas-automatizaciones.md con los umbrales de definiciones/reglas.yaml (automatizaciones). Deterministas: deciden CUÁNDO actuar y QUÉ detectar; nunca deciden sobre una persona.
// Sin dependencias: lo usan la demo local (demo.js), el vídeo (exportar-video.js) y los nodos de código de n8n (exportar-n8n.js).

// Umbrales con nombres cortos, leídos de reglas.yaml (automatizaciones): seguimiento y centinela
const umbralesAutomatizaciones = reglas => ({
  diasEntreAvisos: reglas.automatizaciones.seguimiento.dias_entre_avisos,
  avisosAntesDeEscalar: reglas.automatizaciones.seguimiento.avisos_antes_de_escalar,
  mesesValidacion: reglas.automatizaciones.centinela.meses_validacion,
  diasDecisionPendiente: reglas.automatizaciones.centinela.dias_decision_pendiente,
});

const dias = (desde, hasta) => Math.round((Date.parse(hasta) - Date.parse(desde)) / 864e5);
const sumarDias = (fecha, n) => new Date(Date.parse(fecha) + n * 864e5).toISOString().slice(0, 10);
const fechaValida = f => /^\d{4}-\d{2}-\d{2}$/.test(String(f || '')) && !isNaN(Date.parse(f));

// Fecha en que toca comprobar un plan: la objetivo si la tiene; si no, el inicio más la duración de su formación
function fechaRevision(plan, catalogo) {
  if (fechaValida(plan.fecha_objetivo)) return plan.fecha_objetivo;
  const f = catalogo.find(c => c.id === plan.formacion_id);
  return fechaValida(plan.fecha_inicio) && f ? sumarDias(plan.fecha_inicio, f.semanas * 7) : '';
}

// ---------- Seguimiento de planes ----------
// Para cada plan activo que ha llegado a su fecha: avisa al manager, le recuerda y, tras varios avisos, escala a People (plazos en reglas.yaml).
// Devuelve las acciones; no escribe nada. avisos y ultimo_aviso viven en la hoja planes-backup.
function seguimientoPlanes(datos, hoy) {
  const U = umbralesAutomatizaciones(datos.reglas);
  const persona = id => datos.empleados.find(e => e.id === id);
  const acciones = [];
  for (const p of datos.planes.filter(x => x.estado === 'activo')) {
    const revision = fechaRevision(p, datos.catalogo);
    if (!revision || hoy < revision) continue; // aún en curso
    const avisos = +p.avisos || 0;
    if (avisos > U.avisosAntesDeEscalar) continue; // ya escalado: lo lleva People
    if (avisos && fechaValida(p.ultimo_aviso) && dias(p.ultimo_aviso, hoy) < U.diasEntreAvisos) continue; // avisado hace poco
    const e = persona(p.empleado_id);
    if (!e || e.estado !== 'activo') continue;
    const m = persona(e.manager_id);
    const sinManager = !m || m.estado !== 'activo'; // p. ej. su manager se ha ido: no hay a quién avisar, va directo a People
    const nivel = datos.skills.find(s => s.empleado_id === e.id && s.skill_id === p.skill_id)?.nivel_validado || 0;
    acciones.push({
      tipo: sinManager || avisos >= U.avisosAntesDeEscalar ? 'escalar' : avisos ? 'recordatorio' : 'aviso', sin_manager: sinManager,
      plan_id: p.plan_id, funcion_id: p.funcion_id, skill_id: p.skill_id, nivel_actual: +nivel, nivel_objetivo: +p.nivel_objetivo, formacion_id: p.formacion_id,
      empleado: { id: e.id, nombre: e.nombre }, manager: m ? { id: m.id, nombre: m.nombre } : null,
      fecha_revision: revision, dias_desde_revision: dias(revision, hoy), avisos: sinManager ? U.avisosAntesDeEscalar + 1 : avisos + 1,
      motivo: sinManager ? `${e.nombre} no tiene un manager activo que pueda validar${m ? ` (${m.nombre} ya no está)` : ''}`
        : `${m.nombre} ha recibido ${avisos} avisos y no ha validado el nivel`,
    });
  }
  return acciones;
}

// ---------- Centinela de riesgo ----------
// Revisión programada: qué está frágil y desde cuándo, qué se ha degradado sin que nadie lo avise y qué está pendiente.
// r = calcular(datos); cambios = comparar(foto anterior, r); historico y alertas = filas de sus hojas.
function vigilar(datos, r, cambios, historico, alertas, hoy) {
  const U = umbralesAutomatizaciones(datos.reglas);
  const nombre = id => datos.empleados.find(e => e.id === id)?.nombre || id;
  // Desde cuándo está cada función en su color actual (racha en el histórico)
  const desde = f => {
    const h = historico.filter(x => x.funcion_id === f.id).sort((a, b) => (a.fecha < b.fecha ? -1 : 1));
    let d = '';
    for (const x of h) if (x.semaforo !== f.semaforo) d = ''; else if (!d) d = x.fecha;
    return d;
  };
  const fragiles = r.funciones.filter(f => f.prioridad === 'P1' || f.prioridad === 'P2').map(f => {
    const d = desde(f);
    return { id: f.id, nombre: f.nombre, area: f.area, semaforo: f.semaforo, prioridad: f.prioridad, cobertura: f.cobertura, objetivo: f.objetivo, desde: d, dias: d ? dias(d, hoy) : null,
      cubren: f.skills.reduce((a, b) => (b.cobertura < a.cobertura ? b : a)).personas.map(nombre) };
  });
  // Validaciones caducadas que sostienen funciones críticas o importantes al límite de su cobertura
  const limite = sumarDias(hoy, -Math.round(U.mesesValidacion * 30.44));
  const caducadas = [];
  for (const f of r.funciones.filter(x => x.criticidad !== 'soporte')) for (const s of f.skills.filter(x => x.cobertura <= f.objetivo)) for (const id of s.personas) {
    const v = datos.skills.find(x => x.empleado_id === id && x.skill_id === s.skill);
    if (v && fechaValida(v.fecha) && v.fecha < limite) caducadas.push({ funcion_id: f.id, skill: s.skill, empleado: nombre(id), validado_por: v.validado_por, fecha: v.fecha, meses: Math.floor(dias(v.fecha, hoy) / 30.44) });
  }
  const planes = datos.planes.filter(p => p.estado === 'activo').map(p => {
    const rev = fechaRevision(p, datos.catalogo);
    return { plan_id: p.plan_id, empleado: nombre(p.empleado_id), skill: p.skill_id, funcion_id: p.funcion_id, formacion_id: p.formacion_id, fecha_revision: rev,
      estado: rev && hoy >= rev ? 'toca validar' : 'en curso', avisos: +p.avisos || 0 };
  });
  const pendientes = alertas.filter(a => a.decision === 'pendiente' && fechaValida(a.fecha) && dias(a.fecha, hoy) >= U.diasDecisionPendiente)
    .map(a => ({ alerta_id: a.alerta_id, accion: a.accion, prioridad: a.prioridad, fecha: a.fecha, dias: dias(a.fecha, hoy) }));
  // Solo People: key people con señales de rotación (nunca va al informe de dirección)
  const kp = new Set(r.key_people.map(k => k.id));
  const senales = r.senales_rotacion.filter(s => kp.has(s.id) && s.nivel_senales !== 'bajo');
  const cuenta = r.funciones.reduce((m, f) => ((m[f.semaforo] = (m[f.semaforo] || 0) + 1), m), { rojo: 0, ambar: 0, verde: 0 });
  // A dirección solo le llega "en seguimiento por People", sin el porqué (prompts/informe-direccion.md, regla 3)
  return { fecha: hoy, umbrales: U, cuenta, cambios, fragiles, key_people: r.key_people.map(k => ({ nombre: k.nombre, rol: k.rol, oculta: k.oculta, funciones: k.funciones.map(f => f.funcion), seguimiento: senales.some(s => s.id === k.id) })),
    caducadas, planes, pendientes, senales };
}

// Mensaje para Claude (prompts/informe-direccion.md): solo datos agregados y organizativos, sin señales ni salarios
function mensajeInforme(h, user) {
  const t = {
    fecha: h.fecha,
    mapa: [`Rojo ${h.cuenta.rojo} · ámbar ${h.cuenta.ambar} · verde ${h.cuenta.verde}`, ...h.fragiles.map(f => `${f.id} ${f.nombre} (${f.area}): ${f.semaforo} ${f.prioridad}, cobertura ${f.cobertura}/${f.objetivo}${f.dias != null ? `, en ${f.semaforo} desde ${f.desde} (${f.dias} días)` : ''}`)].join('\n'),
    key_people: h.key_people.map(k => `${k.nombre} · ${k.rol} · ${k.funciones.join(', ')}${k.oculta ? ' · oculta' : ''}${k.seguimiento ? ' · en seguimiento por People' : ''}`).join('\n'),
    cambios_mes: h.cambios.length ? h.cambios.map(c => `${c.id} ${c.nombre}: ${c.de} → ${c.a} (${c.cambio})`).join('\n') : 'Sin cambios respecto al último recálculo.',
    planes_backup: h.planes.map(p => `${p.plan_id} ${p.empleado} · ${p.skill} (${p.funcion_id}) · revisión ${p.fecha_revision || 'sin fecha'} · ${p.estado}`).join('\n') || 'Ninguno.',
    alertas_mes: [...h.pendientes.map(a => `${a.alerta_id} ${a.accion}: pendiente desde hace ${a.dias} días`),
      ...(h.caducadas.length ? [`${h.caducadas.length} validaciones de skills con más de ${h.umbrales.mesesValidacion} meses sostienen funciones al límite`] : [])].join('\n') || 'Ninguna.',
  };
  return user.replace(/\{\{(\w+)\}\}/g, (m, k) => (k in t ? t[k] : m));
}

// Informe por reglas, con las secciones del prompt: si Claude no responde, el informe sale igual
function informePorReglas(h) {
  const p1 = h.fragiles.filter(f => f.prioridad === 'P1');
  const lin = xs => xs.map(x => `- ${x}`).join('\n');
  return [
    '## En una frase',
    `${h.cuenta.rojo} funciones en rojo, ${h.cuenta.ambar} en ámbar y ${h.cuenta.verde} en verde${p1.length ? `; ${p1.length} de prioridad 1` : ''}.`,
    '## Dónde somos frágiles',
    lin(h.fragiles.map(f => `**${f.id} ${f.nombre}** (${f.area}): ${f.prioridad}, cobertura ${f.cobertura} de ${f.objetivo}${f.dias != null ? `, ${f.dias} días en ${f.semaforo}` : ''}${f.cubren.length ? `. Depende de: ${f.cubren.join(', ')}` : '. Hoy no la cubre nadie'}`)),
    '## Qué ha cambiado',
    h.cambios.length ? lin(h.cambios.map(c => `${c.id} ${c.nombre}: ${c.de} → ${c.a}`)) : 'Nada desde el último recálculo.',
    '## Dependencia de personas',
    lin(h.key_people.map(k => `${k.nombre} (${k.rol}): ${k.funciones.join(', ')}${k.oculta ? ' · **oculta**' : ''}${k.seguimiento ? ' · en seguimiento por People' : ''}`)),
    '## Qué estamos haciendo',
    h.planes.length ? lin(h.planes.map(p => `Plan ${p.plan_id}: ${p.empleado} en ${p.skill} (${p.funcion_id}), ${p.estado}${p.fecha_revision ? `, revisión ${p.fecha_revision}` : ''}`)) : 'Ningún plan activo.',
    '## Qué necesitamos de dirección',
    lin([
      ...p1.filter(f => !f.cubren.length).map(f => `Decidir cómo cubrir **${f.id}**: hoy no la sabe hacer nadie (formar fuera, contratar o apoyo externo).`),
      ...h.pendientes.slice(0, 2).map(a => `Desbloquear ${a.alerta_id} (${a.accion}): ${a.dias} días sin decisión.`),
      ...(h.caducadas.length ? [`Pedir a los managers que revaliden ${h.caducadas.length} skills con más de ${h.umbrales.mesesValidacion} meses: el mapa vale lo que valga la validación.`] : []),
    ].slice(0, 3)),
  ].join('\n\n');
}

// Markdown sencillo (títulos, listas, negrita) → HTML de email
function mdAHtml(md) {
  const escapar = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const inline = s => escapar(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  const out = []; let lista = false;
  for (const l of String(md).replace(/\r/g, '').split('\n')) {
    const li = l.match(/^\s*(?:[-*]|\d+\.)\s+(.*)/);
    if (li) { if (!lista) { out.push('<ul>'); lista = true; } out.push(`<li>${inline(li[1])}</li>`); continue; }
    if (lista) { out.push('</ul>'); lista = false; }
    const t = l.match(/^(#{1,4})\s+(.*)/);
    if (t) out.push(`<h${Math.min(t[1].length + 2, 5)}>${inline(t[2])}</h${Math.min(t[1].length + 2, 5)}>`);
    else if (l.trim()) out.push(`<p>${inline(l)}</p>`);
  }
  if (lista) out.push('</ul>');
  return out.join('\n');
}


// Herramientas del Asistente de People (D-25): lo que un agente con Claude puede consultar para responder a People.
// El modelo decide qué herramienta usar y en qué orden; las cifras las calcula siempre el motor (calcular, comparar, vacante).
// Solo lectura: ninguna herramienta escribe. Privacidad por construcción: ninguna devuelve salarios, bandas, evaluaciones
// ni señales de rotación (para eso no hay herramienta, y el prompt manda negarse).
// Sin dependencias: recibe calcular, comparar y vacante como parámetro, para servir igual en Node y en los nodos de n8n.

const HERRAMIENTAS = [
  { name: 'consultar_mapa', description: 'Estado actual del mapa de cobertura: cuántas funciones hay en rojo, ámbar y verde, cuáles están en riesgo (con su prioridad, cobertura y quién las sostiene) y quiénes son las key people.',
    input_schema: { type: 'object', properties: {} } },
  { name: 'buscar_persona', description: 'Busca personas por nombre o id (por ejemplo "Carmen" o "E011"). Devuelve rol, área, manager, skills validadas y las funciones en las que es key person. No incluye datos salariales ni de desempeño.',
    input_schema: { type: 'object', properties: { texto: { type: 'string', description: 'Nombre, apellido o id de la persona' } }, required: ['texto'] } },
  { name: 'simular_baja', description: 'Simula qué pasaría si una persona dejara la compañía, sin cambiar nada: qué funciones empeoran, quién pasa a ser key person y qué candidatos internos podrían cubrir su puesto, con sus brechas.',
    input_schema: { type: 'object', properties: { empleado_id: { type: 'string', description: 'Id de la persona, por ejemplo E011. Si solo tienes el nombre, usa antes buscar_persona.' } }, required: ['empleado_id'] } },
  { name: 'candidatos_para_funcion', description: 'Para una función (por ejemplo CUS-02), devuelve las skills que pide, quién la cubre hoy, las personas a un nivel de distancia (indicando si tienen interés declarado) y la formación del catálogo que cerraría la brecha.',
    input_schema: { type: 'object', properties: { funcion_id: { type: 'string', description: 'Id de la función, por ejemplo CUS-02' } }, required: ['funcion_id'] } },
  { name: 'madurez_ia', description: 'Madurez IA por área (media de uso diario, automatización y criterio), siempre agregada: no se publica ningún grupo de menos de 5 personas.',
    input_schema: { type: 'object', properties: {} } },
];

const normalizar = t => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();

function ejecutarHerramienta(nombre, entrada, datos, motor) {
  const { calcular, comparar, vacante } = motor;
  const r = calcular(datos);
  const persona = id => datos.empleados.find(e => e.id === id);
  const nombreDe = id => persona(id)?.nombre || id;
  const skillNombre = id => datos.taxonomia.skills.find(s => s.id === id)?.nombre || id;
  const resumenFuncion = f => ({ id: f.id, nombre: f.nombre, area: f.area, criticidad: f.criticidad, semaforo: f.semaforo, prioridad: f.prioridad,
    cobertura: f.cobertura, objetivo: f.objetivo, respuesta: f.respuesta === 'redisenar' ? 'rediseñar con IA' : 'cubrir',
    sostienen: f.skills.reduce((a, b) => (b.cobertura < a.cobertura ? b : a)).personas.map(nombreDe) });
  const keyPeople = res => res.key_people.map(k => ({ nombre: k.nombre, rol: k.rol, area: k.area, oculta: k.oculta, funciones: k.funciones.map(f => f.funcion) }));
  const cuenta = res => res.funciones.reduce((m, f) => ((m[f.semaforo] = (m[f.semaforo] || 0) + 1), m), { rojo: 0, ambar: 0, verde: 0 });

  if (nombre === 'consultar_mapa') {
    return { mapa: cuenta(r), funciones_en_riesgo: r.funciones.filter(f => f.semaforo !== 'verde').map(resumenFuncion), key_people: keyPeople(r) };
  }
  if (nombre === 'buscar_persona') {
    const q = normalizar(entrada.texto);
    if (!q) return { error: 'Falta el texto a buscar' };
    const halladas = datos.empleados.filter(e => normalizar(e.id) === q || normalizar(e.nombre).includes(q)).slice(0, 5);
    if (!halladas.length) return { personas: [], nota: `No hay nadie que coincida con "${entrada.texto}"` };
    return { personas: halladas.map(e => {
      const kp = r.key_people.find(k => k.id === e.id);
      return { id: e.id, nombre: e.nombre, rol: e.rol, area: e.area, estado: e.estado, manager: nombreDe(e.manager_id),
        skills_validadas: datos.skills.filter(s => s.empleado_id === e.id && +s.nivel_validado > 0).map(s => ({ skill: skillNombre(s.skill_id), nivel: +s.nivel_validado })),
        key_person_en: kp ? kp.funciones.map(f => f.funcion) : [] };
    }) };
  }
  if (nombre === 'simular_baja') {
    const id = String(entrada.empleado_id || '').trim().toUpperCase();
    const e = persona(id);
    if (!e) return { error: `No existe ninguna persona con id ${id}. Usa buscar_persona.` };
    if (e.estado !== 'activo') return { error: `${e.nombre} ya no está activa: no se puede simular su baja.` };
    const vac = vacante(datos, id);
    const tras = calcular({ ...datos, empleados: datos.empleados.map(x => (x.id === id ? { ...x, estado: 'baja' } : x)) });
    const cambios = comparar(r, tras).map(c => ({ ...c, nombre: tras.funciones.find(f => f.id === c.id).nombre }));
    const antes = new Set(r.key_people.map(k => k.id));
    return {
      simulacion: `Baja de ${e.nombre} (${e.rol}). No se ha cambiado nada en el HRIS.`,
      funciones_que_empeoran: cambios.filter(c => c.cambio === 'empeora').map(c => ({ id: c.id, nombre: c.nombre, de: c.de, a: c.a, cobertura_antes: c.cobertura_antes, cobertura_despues: c.cobertura_despues })),
      mapa_antes: cuenta(r), mapa_despues: cuenta(tras),
      nuevas_key_people: keyPeople(tras).filter(k => !antes.has(tras.key_people.find(x => x.nombre === k.nombre).id)),
      puesto: { rol: vac.rol, equipo: vac.equipo, perfil: vac.perfil.map(p => ({ skill: skillNombre(p.skill), nivel: p.nivel })),
        candidatos_internos: vac.candidatos.map(c => ({ nombre: c.nombre, rol: c.rol, cumple: `${c.cumple} de ${c.de}`,
          brechas: c.brechas.map(b => ({ skill: skillNombre(b.skill), tiene: b.tiene, necesita: b.necesita, formacion: b.formacion })), ya_es_key_person_en: c.key_person_en })) },
    };
  }
  if (nombre === 'candidatos_para_funcion') {
    const fid = String(entrada.funcion_id || '').trim().toUpperCase();
    const f = r.funciones.find(x => x.id === fid);
    if (!f) return { error: `No existe la función ${fid}. Usa consultar_mapa para ver los ids.` };
    return { ...resumenFuncion(f), skills: f.skills.map(s => ({ skill: skillNombre(s.skill), nivel_minimo: s.nivel_minimo, cobertura: s.cobertura, semaforo: s.semaforo,
      cubren: s.personas.map(nombreDe), backups_en_desarrollo: s.backups_en_desarrollo.map(nombreDe),
      a_un_nivel: (s.candidatos || []).map(c => ({ nombre: c.nombre, area: c.area, con_interes: c.con_interes, ya_es_key_person: c.es_key_person })),
      formacion: (s.formacion || []).map(id => { const c = datos.catalogo.find(x => x.id === id); return { id, nombre: c.nombre, semanas: c.semanas }; }) })) };
  }
  if (nombre === 'madurez_ia') return { madurez_por_area: r.madurez_ia };
  return { error: `No existe la herramienta ${nombre}` };
}

// Una línea legible de lo que devolvió una herramienta, para enseñar cómo ha razonado el agente
function resumenResultado(nombre, res) {
  if (res.error) return res.error;
  if (nombre === 'consultar_mapa') return `Mapa ${res.mapa.rojo}·${res.mapa.ambar}·${res.mapa.verde}; ${res.funciones_en_riesgo.length} funciones en riesgo; ${res.key_people.length} key people`;
  if (nombre === 'buscar_persona') return res.personas.length ? res.personas.map(p => `${p.id} ${p.nombre} (${p.rol})`).join('; ') : res.nota;
  if (nombre === 'simular_baja') {
    const nf = res.funciones_que_empeoran.length, nc = res.puesto.candidatos_internos.length;
    return `${nf === 1 ? '1 función empeora' : `${nf} funciones empeoran`} (${res.funciones_que_empeoran.map(f => `${f.id} ${f.de}→${f.a}`).join(', ') || 'ninguna'}); ${nc === 1 ? '1 candidato interno' : `${nc} candidatos internos`}`;
  }
  if (nombre === 'candidatos_para_funcion') return `${res.id} ${res.semaforo} ${res.prioridad}; cobertura ${res.cobertura}/${res.objetivo}`;
  if (nombre === 'madurez_ia') return `${res.madurez_por_area.length} áreas publicadas`;
  return '';
}


// Utilidades de los nodos de código de n8n: leer el HRIS y preparar las filas a escribir.
// Los escenarios no hablan con Google Sheets: llaman al subworkflow HRIS (D-24), que lee y escribe las hojas.
// exportar-n8n.js las concatena con el motor (cobertura.js), la propuesta (propuesta.js) y las filas (hojas.js).

// Hojas del HRIS y el nodo que las lee dentro del subworkflow HRIS. bandas y encuesta no cambian en la demo: vienen de definiciones.json (repo).
const LECTURAS = { empleados: 'Leer empleados', 'skills-empleados': 'Leer skills', 'planes-backup': 'Leer planes', alertas: 'Leer alertas', cobertura: 'Leer cobertura', 'historico-semaforo': 'Leer histórico',
  'key-people': 'Leer key-people', bandeja: 'Leer bandeja' };
// Cómo escribe el HRIS cada hoja (operación escribir): actualizar por clave, añadir o actualizar por clave, añadir, o vaciar y volver a escribir
const ESCRITURAS = {
  empleados: { op: 'update', clave: 'id' },
  'skills-empleados': { op: 'update', clave: 'row_number' },
  'skills-empleados (nueva)': { op: 'append', hoja: 'skills-empleados' }, // una skill que la persona no tenía
  'planes-backup': { op: 'appendOrUpdate', clave: 'plan_id' },
  alertas: { op: 'appendOrUpdate', clave: 'alerta_id' },
  cobertura: { op: 'appendOrUpdate', clave: 'funcion_id' },
  'historico-semaforo': { op: 'append' },
  'key-people': { op: 'reemplazar' },
  bandeja: { op: 'append' },
};
const hoyISO = () => new Date().toISOString().slice(0, 10);
// Hojas que el reinicio (escenario 0) vuelve a cargar desde salidas/sheets/; alertas y bandeja se vacían sin más
const HOJAS_INICIALES = ['empleados', 'skills-empleados', 'planes-backup', 'cobertura', 'key-people', 'historico-semaforo'];
// Fecha de trabajo de las automatizaciones con calendario: la del formulario "Ejecutar ahora" ("+12 semanas" o una fecha exacta) o hoy
function fechaDe(cfg) {
  const f = String(cfg.fecha || '').trim();
  if (fechaValida(f)) return f;
  const s = String(cfg.cuando || '').match(/\+\s*(\d+)\s*semana/);
  return s ? sumarDias(hoyISO(), +s[1] * 7) : hoyISO();
}

// Lo que devuelve el nodo "Leer HRIS" → { hoja: { filas: [{ ...columnas, _fila }] } }. _fila es la fila real (row_number).
function tablas() {
  const crudo = $('Leer HRIS').first().json.tablas || {};
  const t = {};
  for (const hoja of Object.keys(LECTURAS)) {
    const items = crudo[hoja] || [];
    t[hoja] = { filas: items.filter(o => Object.keys(o).some(k => k !== 'row_number' && o[k] !== '' && o[k] != null)).map(o => {
      const f = { _fila: o.row_number };
      for (const [k, v] of Object.entries(o)) if (k !== 'row_number') f[k] = v == null ? '' : String(v);
      return f;
    }) };
  }
  return t;
}

// Enlace para ver el HRIS (en la demo, el Sheet): lo da el propio HRIS al leer
function enlaceHris() { try { return $('Leer HRIS').first().json.enlace || ''; } catch (err) { return ''; } }

function datosDesde(T, defs) {
  return {
    funciones: defs.funciones, taxonomia: defs.taxonomia, areas: defs.areas, catalogo: defs.catalogo,
    bandas: defs.bandas, encuesta: defs.encuesta, reglas: defs.reglas,
    empleados: T['empleados'].filas, skills: T['skills-empleados'].filas, planes: T['planes-backup'].filas,
  };
}

// Foto anterior = lo que muestra ahora la hoja cobertura (siempre refleja el último recálculo)
function fotoActual(T) {
  return { funciones: T['cobertura'].filas.map(x => ({ id: x.funcion_id, semaforo: x.semaforo, cobertura: +x.cobertura, nombre: x.nombre })) };
}

// ---------- Filas a escribir: cada una lleva _hoja para que el desvío la mande a su nodo ----------
const valor = v => (v == null ? '' : typeof v === 'string' && /^-?\d+(\.\d+)?$/.test(v) && !/^0\d/.test(v) ? +v : v);
const fila = (hoja, obj, columnas = Object.keys(obj).filter(k => !k.startsWith('_'))) =>
  ({ _hoja: hoja, ...Object.fromEntries(columnas.map(c => [c, valor(obj[c])])) });
const filasDe = (hoja, cols, arrays) => arrays.map(a => fila(hoja, Object.fromEntries(cols.map((c, i) => [c, a[i]]))));

// Mapa tras un recálculo: cobertura (por funcion_id), key-people (se vacía y se reescribe) y foto en el histórico
function filasMapa(r, datos, evento, fecha = hoyISO()) {
  const nombre = id => datos.empleados.find(e => e.id === id)?.nombre || id;
  return [
    ...filasDe('cobertura', COLS.cobertura, filasCobertura(r, nombre)),
    ...filasDe('key-people', COLS.keyPeople, filasKeyPeople(r)),
    ...filasDe('historico-semaforo', COLS.historico, filasHistorico(r, fecha, evento)),
  ];
}

// ---------- Email (HTML sencillo, se ve bien en Gmail) ----------
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = cuerpo => `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:680px">${cuerpo}<p style="color:#888;font-size:12px;margin-top:24px">Acme People OS · datos ficticios · generado automáticamente</p></div>`;
function listaCambios(cambios) {
  return `<ul>${cambios.map(c => `<li><b>${esc(c.id)}</b> ${esc(c.nombre)}: ${ICONO[c.de]} → ${ICONO[c.a]} (cobertura ${c.cobertura_antes} → ${c.cobertura_despues})</li>`).join('')}</ul>`;
}


// ===== Nodo =====
// Escenario 0 · nodo "Panel": la página de entrada para quien prueba la demo sin instalar nada (D-22).
// Lee el Sheet en cada visita y enseña: qué hacer ahora (según el estado), el mapa en vivo, las decisiones pendientes con su
// botón Aprobar y la bandeja de People (copia de cada email que ha enviado el sistema). No escribe nada.
const cfg = $('Configuración').first().json;
const T = tablas();
const base = String(cfg.webhookUrl || '').replace(/acme-panel.*$/, ''); // …/webhook/ de esta misma instancia
const url = { aprobar: base + 'acme-aprobar', reiniciar: base + 'acme-reiniciar', panel: base + 'acme-panel', asistente: base + 'acme-asistente' };
const configurado = u => u && !/^PEGAR_/.test(u);

const empleados = T['empleados'].filas, alertas = T['alertas'].filas, planes = T['planes-backup'].filas;
const mapa = T['cobertura'].filas, kp = T['key-people'].filas, bandeja = T['bandeja'].filas;
const elena = empleados.find(e => e.id === 'E007');

// ---------- Qué hacer ahora: los pasos de la historia y si ya están hechos ----------
const backupJavier = alertas.find(a => a.tipo_accion === 'backup' && a.empleado_id === 'E009');
const planJavier = planes.find(p => p.empleado_id === 'E009' && p.skill_id === 'gestion-claves' && /^ALR/.test(p.origen || ''));
const enlace = (u, texto) => (configurado(u) ? `<a class="btn" href="${u}" target="_blank">${texto} ↗</a>` : `<span class="falta">${texto}: falta configurar la URL</span>`);
const pasos = [
  { t: 'Registrar la baja de Elena, responsable de custodia', d: 'Formulario de baja con el id <b>E007</b>. El sistema recalcula el mapa y prepara una propuesta para People.',
    hecho: elena && elena.estado === 'baja', accion: enlace(cfg.url_form_baja, 'Formulario de baja') },
  { t: 'Decidir cómo cubrir su puesto', d: 'En <i>Decisiones pendientes</i>, aprueba la opción A (buscar fuera) o la B (mover a Marcos). La otra se descarta sola.',
    hecho: alertas.some(a => /^VAC-/.test(a.grupo || '') && a.decision === 'aprobada') },
  { t: 'Aprobar el plan de backup de Javier', d: `${backupJavier ? `<b>${esc(backupJavier.alerta_id)}</b>: c` : 'C'}on un plan activo, <i>Gestión de claves</i> pasa de rojo a ámbar.`,
    hecho: backupJavier && backupJavier.decision === 'aprobada' },
  { t: 'Tres meses después: el seguimiento de planes', d: 'Formulario <i>Ejecutar ahora</i> → <b>seguimiento</b>, <b>+12 semanas</b>. Nadie le pide nada: la automatización ve que el plan de Javier ha llegado a su fecha y escribe a su manager. Míralo en la bandeja.',
    hecho: planJavier && (+planJavier.avisos > 0 || planJavier.estado === 'completado'), accion: enlace(cfg.url_form_automatizaciones, 'Formulario «Ejecutar ahora»') },
  { t: 'El manager valida a Javier', d: 'Pulsa <i>Validar a Javier</i> en el aviso de la bandeja (o abre el formulario de skill con <b>E009 · gestion-claves · 3 · E008</b>). <i>Gestión de claves</i> vuelve a verde.',
    hecho: planJavier && planJavier.estado === 'completado', accion: enlace(cfg.url_form_skill, 'Formulario de skill') },
  { t: 'Si nadie responde (opcional)', d: '<i>Ejecutar ahora</i> → seguimiento con <b>+13</b> y después <b>+14 semanas</b>: recuerda al manager y, tras dos avisos, escala a People.',
    hecho: alertas.some(a => /^SEG-/.test(a.grupo || '')), opcional: true },
  { t: 'El centinela: el informe del mes', d: '<i>Ejecutar ahora</i> → <b>centinela</b>, <b>+14 semanas</b>. Recalcula sin que nadie lo pida y deja en la bandeja el informe para dirección.',
    hecho: bandeja.some(b => /informe para dirección/.test(b.asunto || '')) },
];
const siguiente = pasos.findIndex(p => !p.hecho && !p.opcional);
const htmlPasos = pasos.map((p, i) => `<li class="${p.hecho ? 'hecho' : i === siguiente ? 'ahora' : ''}${p.opcional ? ' opcional' : ''}">
  <div class="n">${p.hecho ? '✓' : i + 1}</div><div><b>${p.t}</b>${i === siguiente ? ' <span class="tag">ahora</span>' : ''}<p>${p.d}</p>${p.accion && !p.hecho ? p.accion : ''}</div></li>`).join('');

// ---------- Mapa en vivo ----------
const cuenta = mapa.reduce((m, f) => ((m[f.semaforo] = (m[f.semaforo] || 0) + 1), m), { rojo: 0, ambar: 0, verde: 0 });
const areas = [];
for (const f of mapa) { let a = areas.find(x => x.n === f.area); if (!a) areas.push(a = { n: f.area, fs: [] }); a.fs.push(f); }
const htmlMapa = areas.map(a => `<div class="area"><span>${esc(a.n)}</span><div class="tiles">${a.fs.map(f =>
  `<div class="tile ${esc(f.semaforo)}" title="${esc(f.nombre)} · cubren: ${esc(f.cubren)}"><b>${esc(f.funcion_id)}${f.prioridad && f.prioridad !== '-' ? ` · ${esc(f.prioridad)}` : ''}</b><span>${esc(f.cobertura)}/${esc(f.objetivo)}</span><small>${esc(f.nombre)}</small></div>`).join('')}</div></div>`).join('');
const htmlKp = kp.map(k => `<li><b>${esc(k.nombre)}</b>${k.oculta === 'si' ? ' <span class="tag oculta">oculta</span>' : ''}<br><small>${esc(k.rol)} · ${esc(k.funciones)}</small></li>`).join('');

// ---------- Decisiones ----------
const pendientes = alertas.filter(a => a.decision === 'pendiente');
const tarjeta = a => `<div class="alerta${a.grupo && /^VAC-/.test(a.grupo) ? ' opcion' : ''}"><div class="cab"><b>${esc(a.alerta_id)}</b>${a.prioridad ? ` <span class="tag">${esc(a.prioridad)}</span>` : ''}${/^VAC-/.test(a.grupo || '') ? ' <span class="tag">elige una</span>' : ''}</div>
  <b>${esc(a.accion)}</b><p>${esc(a.por_que)}</p>${a.riesgo_si_no ? `<p class="riesgo">${esc(a.riesgo_si_no)}</p>` : ''}<a class="btn" href="${url.aprobar}?alerta=${encodeURIComponent(a.alerta_id)}">Aprobar ${esc(a.alerta_id)}</a></div>`;
const decididas = alertas.filter(a => a.decision !== 'pendiente');
const htmlDecisiones = (pendientes.length ? pendientes.map(tarjeta).join('') : '<p class="vacio">Nada pendiente.</p>')
  + (decididas.length ? `<details><summary>Ya decididas (${decididas.length})</summary><ul>${decididas.map(a => `<li><b>${esc(a.alerta_id)}</b> ${esc(a.accion)} · <span class="dec ${esc(a.decision)}">${esc(a.decision)}</span></li>`).join('')}</ul></details>` : '');

