const htmlBandeja = correos.length ? correos.map((c, i) => `<details${i === 0 ? ' open' : ''}><summary><small>${esc(c.fecha)}</small> ${esc(c.asunto)}</summary><div class="correo">${c.html}</div></details>`).join('')
